from PIL import Image,ImageDraw,ImageFilter
import numpy as np
from pathlib import Path
p=Path('output/imagegen/pet-memorial-sunburst-v8');src=Image.open('output/imagegen/pet-memorial-sunburst-v7/walk-sw.png').convert('RGBA');mask=Image.new('L',src.size)
# Skin boundaries only, excluding the gold cuff and sleeve; coordinates are frame-local.
polys=[
[[(82,198),(94,199),(94,205),(90,212),(83,217),(79,219),(74,217),(75,211),(77,207)],[(181,207),(195,204),(201,210),(203,216),(208,224),(206,229),(202,229),(199,234),(194,237),(189,235),(188,229),(184,227),(179,228),(179,220)]],
[[(99,198),(110,201),(108,209),(104,214),(98,217),(96,221),(91,218),(89,213),(92,207)],[(179,209),(194,207),(198,211),(199,220),(198,228),(193,236),(190,237),(187,234),(184,234),(181,229),(178,228),(176,224),(177,216)]],
[[(102,199),(114,202),(113,208),(110,214),(105,219),(100,221),(98,218),(95,215),(96,209)],[(188,208),(202,206),(207,212),(207,220),(206,230),(201,236),(197,237),(193,232),(190,232),(187,227),(184,227),(185,216)]],
[[(111,201),(124,203),(123,211),(120,216),(116,220),(111,225),(107,223),(105,219),(106,211)],[(185,208),(200,207),(203,213),(203,222),(201,230),(197,233),(194,231),(191,233),(187,230),(184,226),(182,223),(182,215)]],
[[(102,202),(115,207),(110,214),(106,218),(101,220),(98,218),(94,221),(91,218),(94,210)],[(153,209),(166,213),(162,220),(157,225),(153,233),(150,235),(148,231),(147,225),(143,222),(143,216)]],
[[(111,207),(124,211),(121,217),(116,224),(113,229),(109,227),(107,226),(105,221),(108,215)],[(163,218),(178,218),(178,228),(175,237),(171,241),(168,238),(166,234),(162,237),(159,234),(159,229),(155,233),(155,227)]],
[[(111,211),(125,214),(124,221),(119,227),(114,231),(109,230),(108,226),(105,225),(106,220)],[(177,219),(192,218),(195,225),(194,233),(192,239),(188,241),(184,238),(179,240),(176,236),(176,231),(172,233),(172,226)]],
[[(111,213),(124,216),(122,224),(118,230),(114,232),(111,230),(108,231),(107,226),(109,220)],[(185,220),(200,219),(204,225),(205,232),(203,238),(200,241),(197,241),(194,237),(192,239),(188,236),(185,237),(182,232),(183,227)]]]
for i,hs in enumerate(polys):
 # Draw at 4x resolution for accurate, antialiased skin boundaries.
 local=Image.new('L',(312*4,416*4));d=ImageDraw.Draw(local)
 for poly in hs:d.polygon([(int(x*4),int(y*4)) for x,y in poly],fill=255)
 local=local.resize((312,416),Image.Resampling.LANCZOS).filter(ImageFilter.GaussianBlur(.5));mask.paste(local,(i%4*312,i//4*416))
a=np.array(src).astype('float32');rgb=a[:,:,:3];lum=(rgb[:,:,0]*.2126+rgb[:,:,1]*.7152+rgb[:,:,2]*.0722)/255;t=np.clip(lum,0,1)**.7
new=np.stack([140+115*t,105+145*t,65+168*t],axis=2)
m=np.array(mask).astype('float32')/255*.90
# Keep transparent background and the exact original alpha unchanged.
m*=a[:,:,3]>20
out=a.copy();out[:,:,:3]=rgb*(1-m[:,:,None])+new*m[:,:,None];out=np.rint(np.clip(out,0,255)).astype('uint8');Image.fromarray(out).save(p/'walk-sw.png');mask.save(p/'skin-color-mask.png')
assert np.array_equal(out[:,:,3],np.array(src)[:,:,3]);assert np.array_equal(out[np.array(mask)==0],np.array(src)[np.array(mask)==0]);print('Local skin color adjustment only; alpha and pixels outside masks unchanged.')
